function importFrom(file, helper, name) {
  let path = relative(dirname(file), helper).replace(/\\/g, '/').replace(/\.ts$/, '.js');
  if (!path.startsWith('.')) path = './' + path;
  return "import { " + name + " } from '" + path + "';\n";
}

